async function begin(withSound){if(!ready)return;input.activate();started=true;$('#start').hidden=true;ui.hud.hidden=false;input.paused=false;settings.on=withSound;configure();if(withSound)sound.unlock().catch(e=>toast('Tap Audio to enable sound. '+e.message,'warning'));toast('Welcome home. Follow the amber MAINTENANCE route for your PM and supplies. Blue leads to the range; red to the canteen; green to the trader.');if(pad)input.device='gamepad';}
