function drawLegacyMap(c,live=false){if(!c)return;const r=c.getBoundingClientRect();if(!r.width||!r.height)return;const ratio=Math.min(2,devicePixelRatio),ww=Math.round(r.width*ratio),hh=Math.round(r.height*ratio);if(c.width!==ww||c.height!==hh){c.width=ww;c.height=hh}const g=c.getContext('2d'),w=c.width,h=c.height;g.clearRect(0,0,w,h);g.fillStyle=live?'rgba(11,24,20,.72)':'#20372c';g.fillRect(0,0,w,h);const b=DATA.bounds,s=Math.min((w-30)/(b.maxX-b.minX),(h-40)/(b.maxZ-b.minZ)),ox=(w-(b.maxX-b.minX)*s)/2,oy=(h-(b.maxZ-b.minZ)*s)/2;const xy=(x,z)=>[ox+(x-b.minX)*s,oy+(z-b.minZ)*s];g.fillStyle='#46747b88';let [sx,sy]=xy(DATA.shore,b.minZ);g.fillRect(sx,sy,(b.maxX-DATA.shore)*s,(b.maxZ-b.minZ)*s);g.strokeStyle='#68876a55';g.lineWidth=1;for(let x=-120;x<=120;x+=40){g.beginPath();g.moveTo(...xy(x,b.minZ));g.lineTo(...xy(x,b.maxZ));g.stroke()}for(let z=-240;z<=40;z+=40){g.beginPath();g.moveTo(...xy(b.minX,z));g.lineTo(...xy(b.maxX,z));g.stroke()}
 g.strokeStyle='#b4ab8377';g.lineWidth=2*ratio;for(const road of DATA.roads){g.beginPath();road.forEach(([x,z],i)=>i?g.lineTo(...xy(x,z)):g.moveTo(...xy(x,z)));g.stroke()}g.strokeStyle='#c1c4ae';g.setLineDash([3*ratio,2*ratio]);g.beginPath();g.moveTo(...xy(-89,-65));g.lineTo(...xy(-89,-249));g.stroke();g.setLineDash([]);
 const p=DATA.pier;g.fillStyle='#9b9774';let [px,pz]=xy(p.minX,p.minZ);g.fillRect(px,pz,(p.maxX-p.minX)*s,(p.maxZ-p.minZ)*s);g.fillStyle='#ced1ad';for(const bb of DATA.buildings){let [x,z]=xy(bb.x-bb.w/2,bb.z-bb.d/2);g.fillRect(x,z,Math.max(3,bb.w*s),Math.max(3,bb.d*s))}g.fillStyle='#b7d7a8';let[bx,bz]=xy(-6,0);g.fillRect(bx,bz,12*s,14*s);g.font=`${10*ratio}px system-ui`;g.fillText('RELAY 07',bx+16*s,bz+10*s);
 for(const k of DATA.landmarks.filter(k=>/Camp 04|Barracks 12/.test(k.name))){const[x,y]=xy(k.x,k.z);g.fillStyle='#a6c596';g.fillRect(x-3,y-3,6,6);if(!live)g.fillText(k.name,x+5,y);}
  for(const m of DATA.missions){if(!['active','available'].includes(state.missions[m.id]))continue;let pinned=state.pinned===m.id;const returnItem=state.bag[m.item]>0;let [x,z]=xy(returnItem?3.7:m.x,returnItem?9.6:m.z);g.save();g.translate(x,z);g.rotate(Math.PI/4);g.strokeStyle=pinned?'#ffe2a0':'#a6a890';g.lineWidth=(pinned?2:1)*ratio;g.strokeRect(-4*ratio,-4*ratio,8*ratio,8*ratio);g.restore();if(pinned&&!live){g.fillStyle='#ffe2a0';g.fillText(returnItem?'RETURN TO RADIO':m.title,x+8*ratio,z-5*ratio)}}
 if(state.corpse){let[x,z]=xy(state.corpse.x,state.corpse.z);g.fillStyle='#e3a096';g.fillText('× PACK',x,z)}
 let[x,z]=xy(player.x,player.z);g.save();g.translate(x,z);g.rotate(-player.yaw);g.fillStyle='#ffffff';g.beginPath();g.moveTo(0,-7*ratio);g.lineTo(-4*ratio,5*ratio);g.lineTo(0,2*ratio);g.lineTo(4*ratio,5*ratio);g.closePath();g.fill();g.restore();g.fillStyle='#ccd8c1';g.font=`${9*ratio}px system-ui`;g.fillText('N ↑',10*ratio,16*ratio);if(live)g.fillText('MAP / VIEW TO CLOSE',10*ratio,h-8*ratio);
}
async function checkOffline(){if(!('serviceWorker'in navigator))return;const reg=await navigator.serviceWorker.ready;(reg.active||navigator.serviceWorker.controller)?.postMessage({type:'cache-all'})}
async function setupOffline(){try{if(!('serviceWorker'in navigator))throw Error('Not supported');await navigator.serviceWorker.register('./sw.js');navigator.serviceWorker.addEventListener('message',e=>{const d=e.data;if(d.type==='cache-progress')offlineStatus=`Downloading offline files: ${d.done} / ${d.total}`;if(d.type==='cache-ready')offlineStatus='Game, Python, textures and sound are ready offline in this browser.';if(d.type==='cache-error')offlineStatus='Offline download incomplete. Keep a connection and retry.';if(panel?.kind==='saves'&&$('#offline-status'))$('#offline-status').textContent=offlineStatus});await checkOffline()}catch{offlineStatus='Offline caching unavailable. Keep an internet connection.'}}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,Math.max(0,(now-lastFrame)/1000||.016));lastFrame=now;if(!world)return;const controls=input.poll(dt);aim=controls.aim;let moving=false;
 if(started&&state&&!input.paused&&!fatal&&!searching){const[mx,my]=controls.move,before={...player};let speed=(crouch?1.45:controls.sprint&&state.stamina>3?4.7:2.8)*(weight>23?.82:1);const next=world.movePlayer(player,(Math.cos(player.yaw)*mx+Math.sin(player.yaw)*my)*speed*dt,(-Math.sin(player.yaw)*mx+Math.cos(player.yaw)*my)*speed*dt);player.x=next.x;player.z=next.z;player.y=next.y??player.y;const d=Math.hypot(player.x-before.x,player.z-before.z);moving=d>.0005;
  if((!moving&&state.enemies.some(e=>e.zone===state.zone&&['windup','leap'].includes(e.mode)))||world.jumpOffset>0){motionTime=Math.min(.7,motionTime+dt);}
  if(moving){motionTime=Math.min(.7,motionTime+dt);footMetres+=d;if(footMetres>(crouch?1.3:controls.sprint?1.8:1.65)){footMetres=0;const surface=world.environment(player).surface;stepIndex=(stepIndex+1)%4;sound.effect('step_'+(surface==='stone'?'stone':'grass')+(stepIndex+1),{bus:'footsteps',volume:crouch?.4:controls.sprint?.85:.65,rate:.97+Math.random()*.06})}}
  if(!tickBusy&&!actionBusy&&now-lastTick>220&&(motionTime>0||Math.abs(player.yaw-state.player.yaw)>.03||Math.abs(player.pitch-state.player.pitch)>.03)){lastTick=now;tickBusy=true;const t=motionTime;motionTime=0;enqueue(tickData(t,t>0,controls.sprint)).finally(()=>tickBusy=false)}
 }
 if(!panel)world.frame(player,dt,{aim,crouch,torch:state?.hand==='torch'&&state.bag.torch>0&&state.torchOn&&state.battery>0,detector,active:moving});
 if(sound.ctx&&started)sound.syncFixtures(world.fixtureStates||[],player,world.time,state.zone);
 if(panel?.kind==='controls'&&panel.tab==='live'&&now-lastHud>125)updateControllerLive7();
 if(started&&state&&now-lastHud>125){lastHud=now;currentTarget=panel||aim?null:world.select();ui.target.classList.toggle('visible',!!currentTarget);if(currentTarget){ui.target.querySelector('strong').textContent=currentTarget.name;ui.target.querySelector('span').textContent=currentTarget.type==='container'?'USE / A to search':currentTarget.type==='pickup'?'Tap to take · A / USE':'A / USE to interact'}sound.listener(player);sound.update(world.environment(player));sound.collect();for(const event of world.weatherEvents.splice(0))if(event.type==='thunder')sound.thunder(event.delay);updateHud();updateHUD8();if(overlay)drawMap($('#live-map'),true);
  if(detector&&!panel){const d=Math.min(...DATA.anomalies.map(a=>Math.hypot(player.x-a.x,player.z-a.z)));if(d<22&&now-lastDetector>500+d*90){lastDetector=now;sound.effect('detector',{volume:.4})}}
  if(!panel&&state.zone!=='base'&&now-lastVoice>6500){let es=state.enemies.filter(e=>e.health>0&&e.zone===state.zone&&e.mode!=='leap'&&Math.hypot(e.x-player.x,e.z-player.z)<30).sort((a,b)=>Math.hypot(a.x-player.x,a.z-player.z)-Math.hypot(b.x-player.x,b.z-player.z));if(es.length){lastVoice=now+Math.random()*9000;const e=es[0],voice=e.kind==='skitter'?'skitter':Math.random()<.45?'whisper':'ghost';sound.effect(voice==='skitter'?'skitter_idle':voice+(Math.floor(Math.random()*3)+1),{bus:'voices',position:e,volume:.8});if(settings.captions)toast(voice==='skitter'?'Rapid clicking, close to the ground.':voice==='whisper'?'A broken voice drifts through the dark.':'A low moan, somewhere nearby.')}}
  if(now-lastSave>5000){lastSave=now;save()}
 }
}
window.addEventListener('resize',()=>{world?.resize();if(panel?.kind==='map')drawMap($('#field-map'));if(panel?.kind==='clean')drawClean();if(overlay)drawMap($('#live-map'),true)});
document.addEventListener('visibilitychange',()=>{if(document.hidden){save();input.clear();if(started)openPanel('pause');sound.suspend()}else sound.resume()});window.addEventListener('pagehide',save);
$('#world').addEventListener('webglcontextlost',e=>{e.preventDefault();fatal=true;save();openPanel('pause');toast('Graphics interrupted. Your progress is saved. Reload to resume.','warning')});
(async()=>{try{world=new World($('#world'),settings.quality);world.reducedMotion=settings.reducedMotion;world.flashEnabled=settings.flashes;sim=new Simulation();let saved=null;try{saved=JSON.parse(localStorage.getItem(SAVE)||'null')}catch{}let r;try{r=await sim.call({type:'init',saved})}catch(e){if(saved){$('#boot').textContent='This saved campaign could not load. '+e.message;const b=document.createElement('button');b.textContent='Keep a snapshot and start again';b.onclick=async()=>{try{localStorage.setItem(SAVE+'-unreadable',JSON.stringify(saved))}catch{}finishBoot(await sim.call({type:'reset'}))};$('.start-actions').appendChild(b);return}throw e}finishBoot(r)}catch(e){$('#boot').textContent='Cannot start: '+e.message+'. WebGL 2 and WebAssembly are required.';console.error(e)}})();
async function finishBoot(r){apply(r,true);configure();$('#boot').textContent='Installing licensed 3D details…';await world.v7Ready;ready=true;$('#boot').textContent='Ready · Stillwater v8 · Input + Python + 3D';$('#begin').disabled=false;$('#silent').disabled=false;if(state.stats.metres>1||state.taken.length)$('#begin').textContent='Continue with sound';setupOffline();requestAnimationFrame(animate)}
window.FieldSignal3D={build:'Stillwater 8.0',getState:()=>structuredClone(state),getPlayer:()=>({...player}),getWorld:()=>world,getSound:()=>sound,getInput:()=>input,getInfo:()=>world?.info(),getReady:()=>ready,act,openPanel,closePanel};

function weaponName(){return state.activeWeapon==='carbine'?'M12 patrol carbine':'PM service pistol'}
function magCapacity(m){return m?.family==='carbine'?12:8}
function weaponChoices(){return `<div class="weapon-choices">${Object.entries(state.weapons).filter(([k,w])=>w.owned).map(([k,w])=>btn((state.activeWeapon===k?'● ':'')+(k==='pm'?'PM pistol':'M12 carbine'),'weapon_select',`data-weapon="${k}"`)).join('')}</div>`}
function marketInfo(){const k=['tuna','battery','wire','med'][Math.floor(state.clock/1440)%4];return{kind:k,text:`Wanted today: ${CAT[k].name}. Paying 2.5× the usual price.`,price:kind=>Math.ceil(CAT[kind].value*(kind===k?2.5:1))}}
let gossipIndex=0;
function gossipText(){const texts=['The west ridge lodge has an upstairs equipment chest. Take the stairs on the right. Someone left a patrol carbine there.','A tiny substation hides a large storage shelter. The stairs go down. Listen before you reach the last step.','The low clicking is a skitter. When it crouches to leap, step sideways. It commits to the place you were standing.','The red areas on your map are anomaly fields. A detector reveals what is hidden; probes reveal a temporary eastern route.','The quartermaster is paying extra for '+CAT[marketInfo().kind].name.toLowerCase()+' today.','Hollowstone cave has survey film in a supply chest. The map changes when you enter. Bring a torch and spare batteries.'];return texts[(gossipIndex++)%texts.length]}
function renderExpansion(){
 const p=panel;if(!['stash','bar','canteen','decorate','weather','trade','bench'].includes(p.kind))return false;
 ui.tabs.innerHTML='';ui.footer.innerHTML='';ui.content.className='';$('#panel-kicker').textContent='BELOW THE PINES / RELAY 07';const small=innerHeight<550,size=small?2:4;
 if(p.kind==='stash'){
  ui.title.textContent='Personal storage';p.tab=p.tab||'put';tabs([['put','Store'],['take','Retrieve'],['mags','Magazines'],['guns','Weapons']]);let rows=[];
  if(p.tab==='put'||p.tab==='take'){const source=p.tab==='put'?state.bag:state.stash,cmd=p.tab==='put'?'stash_put':'stash_take';rows=Object.entries(source).filter(([k,n])=>n>0&&CAT[k].category!=='mission').map(([k,n])=>item(CAT[k].icon,CAT[k].name+' ×'+n,`${(CAT[k].weight*n).toFixed(2)} kg`,btn('1',cmd,`data-kind="${k}" data-count="1"`)+btn('All',cmd,`data-kind="${k}" data-count="${n}"`,n===1)));}
  else if(p.tab==='mags'){rows=[...state.magazines.map(m=>item('▥','Carried '+m.id+' · '+m.rounds+'/'+magCapacity(m),m.family==='carbine'?'M12 magazine':'PM magazine',btn('Store','stash_mag',`data-id="${m.id}"`,Object.values(state.weapons).some(w=>w.inserted===m.id)))),...state.storedMagazines.map(m=>item('▥','Stored '+m.id+' · '+m.rounds+'/'+magCapacity(m),'Ammunition preserved',btn('Take','unstash_mag',`data-id="${m.id}"`)))];}
  else rows=Object.entries(state.weapons).filter(([k,w])=>w.owned||state.storedWeapons[k]).map(([k,w])=>item('⌐',k==='pm'?'PM pistol':'M12 carbine',w.owned?'Carried. Unload before storing.':'Stored safely',btn(w.owned?'Store':'Take',w.owned?'stash_weapon':'unstash_weapon',`data-weapon="${k}"`)));
  ui.content.innerHTML=`<div class="loot-summary"><strong>${weight.toFixed(1)} / 30 kg carried</strong><span>Permanent room storage</span></div><div class="stack-list">${pageRows(rows,size).join('')||notice('Nothing in this section.')}</div>`;pager(rows.length,size);
 }else if(p.kind==='bar'||p.kind==='canteen'){
  const bar=p.kind==='bar';ui.title.textContent=bar?'The Last Light · Vera':'Canteen · Nadia';ui.content.innerHTML=`<p class="npc-line">${bar?'“Still in one piece, comrade? Sit a moment.”':'“You cannot live on adrenaline. Hot stew is ready.”'}</p><p class="notice" id="gossip-text">${bar?gossipText():'A meal restores 50 food and 10 thirst. Clean water restores 45 thirst.'}</p><div class="action-grid">${bar?btn('Tea · 12 cr','bar_drink'):btn('Hot meal · 25 cr','meal')}${bar?btn('Hear gossip','gossip'):btn('Water · 8 cr','drink')}${btn('Leave counter','resume')}</div><p class="fine">${state.credits} credits · Food ${Math.ceil(state.food)}% · Water ${Math.ceil(state.thirst)}%</p>`;footer('This is a safe place. The field waits outside.');
 }else if(p.kind==='decorate'){
  ui.title.textContent='Your quarters';p.tab=p.tab||'wallA';tabs([['wallA','Wall A'],['wallB','Wall B'],['fittings','Fittings']]);let rows=[];
  if(p.tab==='fittings'){rows=[item('▱','Bedside rug','A little warmth underfoot',btn(state.decor.rug?'Roll away':'Place rug','decorate',`data-slot="rug" data-enabled="${!state.decor.rug}"`,!state.roomOwned.includes('rug'))),item('◒','Desk lamp','Warm amber or cool blue',btn('Warm','decorate','data-slot="lamp" data-kind="warm"')+btn('Blue','decorate','data-slot="lamp" data-kind="blue"',!state.roomOwned.includes('lamp_blue')))];}
  else rows=['none',...state.roomOwned.filter(k=>k.startsWith('poster_'))].map(k=>item('▤',k==='none'?'Bare wall':CAT[k].name,state.decor[p.tab]===k?'Currently displayed':'Original fictional film print',btn('Place','decorate',`data-slot="${p.tab}" data-kind="${k}"`)));
  ui.content.innerHTML=notice('Buy original prints and room fittings from the quartermaster. Placement is saved with your campaign.')+`<div class="stack-list">${pageRows(rows,size).join('')}</div>`;pager(rows.length,size);
 }else if(p.kind==='weather'){
  ui.title.textContent='Weather & atmosphere';p.tab=p.tab||'weather';tabs([['weather','Weather'],['sound','Sound & lights']]);
  ui.content.innerHTML=p.tab==='weather'?notice('Automatic weather changes as expedition time passes. Choose an override to test the atmosphere now.')+`<div class="action-grid">${['auto','clear','rain','fog','storm'].map(m=>btn((state.weather.override===m?'● ':'')+m[0].toUpperCase()+m.slice(1),'weather',`data-mode="${m}"`)).join('')}</div><p class="fine">Current sky: ${state.weather.mode}. Shelters reduce weather sound; caves and the base keep rain outside.</p>`:`${slider('weather','Weather audio',Math.round(settings.weather*100))}${toggle('npcVoice','Spoken NPC greetings',settings.npcVoice)}${toggle('flashes','Gentle lightning flashes',settings.flashes)}${toggle('reducedMotion','Reduce ambient motion',settings.reducedMotion)}${notice('Lightning flashes are off by default. Reduced motion also suppresses flashes and fluorescent-light flicker. Speech uses the voice available on your device.')}`;footer('Music, footsteps and drone retain their separate controls.');
 }else if(p.kind==='trade'){
  ui.title.textContent='Mikhail · quartermaster';p.tab=p.tab||'buy';tabs([['buy','Buy'],['sell','Sell'],['decor','Your room']]);const market=marketInfo();let keys=Object.keys(CAT).filter(k=>p.tab==='decor'?CAT[k].category==='decor':p.tab==='sell'?state.bag[k]>0&&!['mission','decor'].includes(CAT[k].category):!['salvage','artefacts','mission','decor'].includes(CAT[k].category));const rows=keys.map(k=>{const c=CAT[k],price=p.tab==='decor'?Math.ceil(c.value*1.7):p.tab==='sell'?market.price(k):Math.ceil(market.price(k)*1.7),owned=state.roomOwned.includes(k);return item(c.icon,c.name,p.tab==='sell'?`${state.bag[k]} carried · ${price} cr each`:`${price} cr${owned?' · owned':''}`,btn(p.tab==='sell'?'Sell 1':'Buy',p.tab==='sell'?'sell':'buy',`data-kind="${k}"`,p.tab==='decor'&&owned))});ui.content.innerHTML=notice(market.text)+`<div class="loot-summary"><strong>${state.credits} credits</strong>${btn('Sell ordinary salvage','sell_junk')}</div><div class="stack-list">${pageRows(rows,size).join('')||notice('No items here.')}</div>`;pager(rows.length,size);
 }else if(p.kind==='bench'){
  ui.title.textContent='Weapon maintenance';ui.content.innerHTML=weaponChoices()+`<div class="weapon-visual"><div class="gun-diagram"></div><div class="status-block"><strong>${weaponName()}</strong><span>${state.weapon.condition.toFixed(1)}% condition</span><span>${state.credits} credits</span></div></div><div class="action-grid">${btn('Clean selected gun','open','data-open="clean"',!state.weapon.owned)}${btn('Weapon handling','open','data-open="weapon"')}${btn('Loot rules','open','data-open="rules"')}</div>${notice('Rub to clean. Each completed stroke restores 1% for 2 credits. Your magazines remain unchanged.')}`;footer('Select PM or M12 above. The workbench must be within reach.');
 }
 return true;
}
function drawMap(c,live=false){
 if(!c||!state)return;const rect=c.getBoundingClientRect();if(!rect.width||!rect.height)return;const ratio=Math.min(2,devicePixelRatio);c.width=Math.round(rect.width*ratio);c.height=Math.round(rect.height*ratio);const g=c.getContext('2d'),w=c.width,h=c.height;g.fillStyle=live?'rgba(9,22,18,.78)':'#20372c';g.fillRect(0,0,w,h);g.font=`${10*ratio}px system-ui`;const zone=state.zone;
 const b=zone==='field'?DATA.bounds:DATA.zones[zone],scale=Math.min((w-40)/(b.maxX-b.minX),(h-55)/(b.maxZ-b.minZ)),ox=(w-(b.maxX-b.minX)*scale)/2,oy=25*ratio+(h-35*ratio-(b.maxZ-b.minZ)*scale)/2,xy=(x,z)=>[ox+(x-b.minX)*scale,oy+(z-b.minZ)*scale];
 if(zone==='field'){
  g.fillStyle='#345f6d';let[x,y]=xy(DATA.shore,b.minZ);g.fillRect(x,y,(b.maxX-DATA.shore)*scale,(b.maxZ-b.minZ)*scale);g.strokeStyle='#b2a58488';g.lineWidth=2*ratio;for(const road of DATA.roads){g.beginPath();road.forEach(([x,z],i)=>i?g.lineTo(...xy(x,z)):g.moveTo(...xy(x,z)));g.stroke()}
  g.strokeStyle='#bfc6b6';g.setLineDash([4,3]);g.beginPath();g.moveTo(...xy(DATA.rail.x,DATA.rail.minZ));g.lineTo(...xy(DATA.rail.x,DATA.rail.maxZ));g.stroke();g.setLineDash([]);
  g.fillStyle='#bfc5ab';for(const bb of DATA.buildings){let[x,y]=xy(bb.x-bb.w/2,bb.z-bb.d/2);g.fillRect(x,y,Math.max(3,bb.w*scale),Math.max(3,bb.d*scale))}let p=DATA.pier;[x,y]=xy(p.minX,p.minZ);g.fillStyle='#a29a75';g.fillRect(x,y,(p.maxX-p.minX)*scale,(p.maxZ-p.minZ)*scale);
  for(const a of DATA.anomalies){const[x,y]=xy(a.x,a.z),r=Math.max(5*ratio,a.radius*scale);g.save();g.beginPath();g.arc(x,y,r,0,Math.PI*2);g.clip();g.fillStyle='#a64d3a88';g.fillRect(x-r,y-r,r*2,r*2);g.strokeStyle='#e9ac78';g.lineWidth=ratio;for(let d=-r*2;d<r*2;d+=5*ratio){g.beginPath();g.moveTo(x-r,y+d);g.lineTo(x+r,y+d+2*r);g.stroke()}g.restore();g.strokeStyle='#da8e6e';g.beginPath();g.arc(x,y,r,0,Math.PI*2);g.stroke();if(!live){g.fillStyle='#f1bd8a';g.fillText('⚠ '+a.name,x+r+3,y)}}
  for(const[name,q]of Object.entries(DATA.zones)){const[x,y]=xy(...q.entry);g.fillStyle=name==='base'?'#b2d8b6':'#bdabdc';g.fillRect(x-3*ratio,y-3*ratio,6*ratio,6*ratio);if(!live)g.fillText(name==='base'?'RELAY 07':q.name,x+7*ratio,y-3*ratio)}
  for(const k of DATA.landmarks.filter(k=>/Camp 04|Barracks 12/.test(k.name))){const[x,y]=xy(k.x,k.z);g.fillStyle='#a6c596';g.fillRect(x-3,y-3,6,6);if(!live)g.fillText(k.name,x+5,y);}
  for(const m of DATA.missions){if(!['active','available'].includes(state.missions[m.id]))continue;const back=state.bag[m.item]>0,[x,y]=xy(back?0:m.x,back?-2:m.z),pin=state.pinned===m.id;g.save();g.translate(x,y);g.rotate(Math.PI/4);g.strokeStyle=pin?'#ffe3a1':'#9da88d';g.lineWidth=(pin?2:1)*ratio;g.strokeRect(-4*ratio,-4*ratio,8*ratio,8*ratio);g.restore();if(pin&&!live){g.fillStyle='#ffe3a1';g.fillText(back?'RETURN TO RELAY':m.title,x+8*ratio,y-4*ratio)}}
 }else{
  g.fillStyle='#4d6556';if(zone==='base'){let[x,y]=xy(-503,0);g.fillRect(x,y,6*scale,46*scale);for(const room of DATA.rooms){let[x,y]=xy(room.x-room.w/2,room.z-room.d/2);g.fillRect(x,y,room.w*scale,room.d*scale);g.fillStyle='#d3dcc3';g.font=`${live?8*ratio:10*ratio}px system-ui`;const text=room.id==='bedroom'?'YOUR ROOM':room.id.toUpperCase();g.fillText(text,x+3,y+room.d*scale/2);g.fillStyle='#4d6556'}}else{const cx=b.x,wide=zone==='cave'?36:26,join=zone==='cave'?21:16;let[x,y]=xy(cx-wide/2,join);g.fillRect(x,y,wide*scale,(b.maxZ-join)*scale);[x,y]=xy(cx-2.7,0);g.fillRect(x,y,5.4*scale,join*scale);g.fillStyle='#b9c3ab';g.fillText('STAIRS ↓',...xy(cx+3,8));for(const cc of DATA.containers.filter(c=>c.zone===zone)){const[x,y]=xy(cc.x,cc.z);g.fillStyle=state.containers[cc.id]?'#7d8574':'#d7bb82';g.fillRect(x-3,y-3,6,6)}}
  for(const q of Object.values(DATA.portals).filter(q=>q.from===zone)){const[x,y]=xy(q.x,q.z);g.fillStyle='#e6cb90';g.fillRect(x-4,y-3,8,6)}
 }
 const mark=waypoint8();if(mark&&mark.zone===zone){const[wx,wy]=xy(mark.x,mark.z);g.strokeStyle='#9ed6d3';g.lineWidth=2*ratio;g.beginPath();g.arc(wx,wy,6*ratio,0,Math.PI*2);g.stroke();g.fillStyle='#b6e7df';if(!live)g.fillText(mark.name,wx+8*ratio,wy);}
 let[x,y]=xy(player.x,player.z);g.save();g.translate(x,y);g.rotate(-player.yaw);g.fillStyle='#fff';g.beginPath();g.moveTo(0,-7*ratio);g.lineTo(-4*ratio,5*ratio);g.lineTo(0,2*ratio);g.lineTo(4*ratio,5*ratio);g.closePath();g.fill();g.restore();g.fillStyle='#d5dec8';g.font=`${10*ratio}px system-ui`;g.fillText(zone==='field'?'N ↑  RED = ANOMALIES':DATA.zones[zone].name.toUpperCase(),10*ratio,16*ratio);g.font=`${9*ratio}px system-ui`;g.fillText(live?'MAP / VIEW TO CLOSE':'WHITE: YOU · GOLD: OBJECTIVE · PURPLE: UNDERGROUND',10*ratio,h-8*ratio);
}

// V7 controller diagnostics are deliberately independent of simulation state.
function renderControls7(){
 const p=panel;p.tab=p.tab||'setup';ui.title.textContent='Controller & input';tabs([['setup','Setup'],['live','Live test'],['buttons','Buttons'],['axes','Sticks']]);
 const d=input.diagnostics();const name=d.pads.find(x=>x.index===d.selected)?.id||'No controller visible to the browser';
 if(p.tab==='setup'){ui.content.innerHTML=`<p class="controller-info">${esc(name)}</p><div class="action-grid">${btn('Activate / rescan','controller-activate')}${btn('Reset standard mapping','reset-map')}${btn('Save diagnostics','controller-export')}</div><a class="clinic-link" href="controller.html" target="_blank" rel="noopener">Open lightweight Controller Clinic</a>${slider('sensitivity','Look sensitivity',settings.sensitivity,.3,2.5,.1)}${slider('deadzone','Stick deadzone',settings.deadzone,.05,.4,.01)}${toggle('invert','Invert vertical look',settings.invert)}${notice('Tap Activate, then press a controller button. Use Safari or the Home Screen app rather than an embedded chat browser. Wired and Bluetooth controllers use this same input path.')}`;footer('A use · LT aim · RT fire · Y pack · R3 jump');}
 else if(p.tab==='live'){ui.content.innerHTML=`<label class="switch-row"><span>Active device</span><select data-controller-device="true"><option value="auto">Most recently used</option>${d.pads.map(x=>`<option value="${x.index}" ${input.preferredIndex===x.index?'selected':''}>${esc(x.id)}</option>`).join('')}</select></label><pre id="controller-live" class="controller-live"></pre><div class="action-grid">${btn('Activate / rescan','controller-activate')}${btn('Save diagnostics','controller-export')}</div>`;footer('A raw input test. No invented or simulated device data.');updateControllerLive7();}
 else if(p.tab==='buttons'){const names=Object.entries({interact:'Use',fire:'Fire',aim:'Aim',pack:'Backpack',magazine:'Magazine',rack:'Rack',probe:'Probe',jump:'Jump',crouch:'Crouch',map:'Map',pause:'Pause',sprint:'Run',safe:'Safety',torch:'Torch',detector:'Detector',heal:'Dressing'});const size=innerHeight<550?4:6;ui.content.innerHTML='<div class="remaps">'+pageRows(names,size).map(([k,l])=>btn(l+' <small>button '+settings.mapping[k]+'</small>','remap',`data-name="${k}"`,!d.pads.length)).join('')+'</div>'+notice('Select an action, then press its new controller button.');pager(names.length,size);}
 else{ui.content.innerHTML='<div class="axis-grid">'+[['moveX','Move X'],['moveY','Move Y'],['lookX','Look X'],['lookY','Look Y']].map(([k,l])=>`<label class="switch-row"><span>${l}</span><select data-axis="${k}">${Array.from({length:Math.max(4,input.pad?.axes.length||4)},(_,i)=>`<option value="${i}" ${settings.mapping[k]===i?'selected':''}>Axis ${i}</option>`).join('')}</select></label>`).join('')+'</div>'+notice('Use Live test to see which axes move. Non-standard controllers can be mapped here.');footer('Movement and look are independently remappable.');}
}
function updateControllerLive7(){const el=$('#controller-live');if(!el)return;const d=input.diagnostics(),p=d.pads.find(x=>x.index===d.selected);el.textContent=[`API ${d.api?'available':'missing'} · HTTPS ${d.secureContext?'yes':'NO'} · focus ${d.focused?'yes':'no'}`,`Top-level ${d.topLevel?'yes':'NO: embedded'} · policy ${d.permissionsPolicy}`,`Devices ${d.pads.length} · ${d.lastReason}`,d.error?`ERROR: ${d.error}`:'',p?`${p.id}\nMapping: ${p.mapping}\nAxes: ${p.axes.map((v,i)=>i+':'+v.toFixed(2)).join(' ')}\nPressed: ${p.pressed.join(', ')||'none'}`:'Tap Activate, then press A or move a stick.'].filter(Boolean).join('\n');}
