function rememberEvent8(e){if(!e?.text||!state||/Cleaning:|Movement|Safety |magazine|Chamber|slide|Loaded |small hop|Weather:/.test(e.text))return;const q={text:e.text,time:Math.floor(state.clock),zone:state.zone};if(journal8.at(-1)?.text===q.text&&journal8.at(-1)?.time===q.time)return;journal8.push(q);if(journal8.length>60)journal8.shift();try{localStorage.setItem('field-signal-v8-journal',JSON.stringify(journal8))}catch{}}
function waypointList8(){return state?.zone==='base'?[['room','Your room',-510,39],['maintenance','Maintenance',-486,27],['quartermaster','Quartermaster',-510,11],['canteen','Canteen',-512,25],['bar','The Last Light',-488,11],['exit','Field exit',-500,2],['range','Range exit',-500,43]].map(([id,name,x,z])=>({id,name,x,z,zone:'base'})):DATA.landmarks.map((m,i)=>({...m,id:'field'+i,zone:'field'}))}
function waypoint8(){const base=[['room','Your room',-510,39],['maintenance','Maintenance',-486,27],['quartermaster','Quartermaster',-510,11],['canteen','Canteen',-512,25],['bar','The Last Light',-488,11],['exit','Field exit',-500,2],['range','Range exit',-500,43]].map(([id,name,x,z])=>({id,name,x,z,zone:'base'}));return[...base,...DATA.landmarks.map((m,i)=>({...m,id:'field'+i,zone:'field'}))].find(m=>m.id===settings.navMark)}
function updateHUD8(){const d=input.diagnostics(),pill=$('#input-pill');if(pill){pill.textContent=d.pads.length?'PAD ✓':'TOUCH';pill.title=d.pads[0]?.id||'No controller exposed';}const mark=waypoint8(),n=$('#nav-line');if(n){if(mark&&mark.zone===state.zone){const dx=mark.x-player.x,dz=mark.z-player.z,angle=-Math.atan2(dx,-dz)-player.yaw,side=Math.atan2(Math.sin(angle),Math.cos(angle));n.textContent=(Math.abs(side)<.45?'↑ ':side>0?'← ':'→ ')+mark.name+' · '+Math.round(Math.hypot(dx,dz))+' m';n.hidden=false}else n.hidden=true;}const stats=$('#performance8');if(stats){stats.hidden=!settings.showStats;const p=world.performanceStats;stats.textContent=`${p?.fps||0} fps · ${p?.draws||0} draws · ${Math.round((p?.triangles||0)/1000)}k triangles`;}}
function renderV8(){if(!panel||!['comfort','journal','waypoints'].includes(panel.kind))return false;const p=panel;ui.tabs.innerHTML='';ui.footer.innerHTML='';ui.content.className='';$('#panel-kicker').textContent='STILLWATER / v8';
 if(p.kind==='comfort'){ui.title.textContent='Display, comfort & diagnostics';p.tab=p.tab||'display';tabs([['display','Display'],['comfort','Comfort'],['tools','Tools']]);if(p.tab==='display')ui.content.innerHTML=`<label class="switch-row"><span>Rendering quality</span><select data-setting="quality">${['low','balanced','high'].map(k=>`<option value="${k}" ${settings.quality===k?'selected':''}>${{low:'Battery saver',balanced:'Balanced',high:'Sharper'}[k]}</option>`).join('')}</select></label>${slider('exposure','Brightness',settings.exposure,.7,1.6,.05)}${slider('fov','Field of view',settings.fov,60,90,1)}${toggle('shadows','Room contact shadows',settings.shadows)}${toggle('vegetation','Dense ground vegetation',settings.vegetation)}`;
 else if(p.tab==='comfort')ui.content.innerHTML=`${toggle('reducedMotion','Reduce ambient motion',settings.reducedMotion)}${toggle('quietLights','Steady light fixtures',settings.quietLights)}<label class="switch-row"><span>Touch controls</span><select data-setting="touch"><option value="auto" ${settings.touch==='auto'?'selected':''}>Automatic</option><option value="always" ${settings.touch==='always'?'selected':''}>Always visible</option></select></label>${notice('No forced camera bob. Steady fixtures remove deliberate electrical flicker without changing the texture fixes.')}`;
 else ui.content.innerHTML=`${toggle('showStats','Performance overlay',settings.showStats)}<div class="action-grid">${btn('Photo view','photo8')}${btn('Export report','report8')}${btn('Controller','open','data-open="controls"')}</div>${notice('Photo view hides the HUD until you tap Exit photo view. The report includes actual rendering, object-placement and controller diagnostics, without uploading anything.')}`;footer('Texture filtering and antialiasing are enabled in every preset.');}
 else if(p.kind==='journal'){ui.title.textContent='Field journal';const rows=[...journal8].reverse(),size=innerHeight<550?3:5;ui.content.innerHTML='<div class="journal-list">'+pageRows(rows,size).map(e=>`<article><small>${String(Math.floor(e.time/60)%24).padStart(2,'0')}:${String(e.time%60).padStart(2,'0')} · ${esc(e.zone)}</small><p>${esc(e.text)}</p></article>`).join('')+'</div>';if(!rows.length)ui.content.innerHTML=notice('Search a container, complete a task or return to the refuge. Important events appear here.');pager(rows.length,size);}
 else{ui.title.textContent='Navigation waypoints';const rows=waypointList8(),size=innerHeight<550?3:5;ui.content.innerHTML='<div class="stack-list">'+pageRows(rows,size).map(m=>item('◇',m.name,Math.round(Math.hypot(m.x-player.x,m.z-player.z))+' metres',btn(settings.navMark===m.id?'Clear':'Mark','waypoint',`data-id="${settings.navMark===m.id?'':m.id}"`))).join('')+'</div>';pager(rows.length,size);}
 return true;}
